2. For each JSON file, load its data and search recursively for the given string within the JSON structure.
3. If the string is found, add the file path to the results list.
4. Return the list of file paths containing the string. If none are found, return an empty list.

### code
```python
import json
from glob import glob
import os

def task_func(directory, string):
    def search_in_data(data):
        if isinstance(data, dict):
            for value in data.values():
                if search_in_data(value):
                    return True
        elif isinstance(data, list):
            for item in data:
                if search_in_data(item):
                    return True
        else:
            if isinstance(data, str) and string in data:
                return True
        return False

    json_files = glob(os.path.join(directory, '**', '*.json'), recursive=True)
    result = []
    for file_path in json_files:
        try:
            with open(file_path, 'r') as f:
                data = json.load(f)
            if search_in_data(data):
                result.append(file_path)
        except (json.JSONDecodeError, UnicodeDecodeError):
            continue
    return result
