1. Load the JSON string into a dictionary.
2. For each value in the dictionary, check its type.
3. If the value is a number (int or float), double it.
4. If the value is a string, extract any numeric substrings using regex and double them.
5. If the value is a list, process each element similarly to double any numeric or number-containing strings.
6. Convert the processed dictionary into a pandas DataFrame.
7. Return the DataFrame.

### code
```python
import json
import re
import pandas as pd
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except:
        return pd.DataFrame()
    for key, value in data.items():
        if isinstance(value, (int, float)):
            data[key] = value * 2
        elif isinstance(value, str):
            numbers = re.findall(r'[-+]?\d*\.?\d+', value)
            if numbers:
                data[key] = [float(num) * 2 for num in numbers]
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, (int, float)):
                    new_list.append(item * 2)
                elif isinstance(item, str):
                    numbers = re.findall(r'[-+]?\d*\.?\d+', item)
                    if numbers:
                        new_list.extend([float(num) * 2 for num in numbers])
                else:
                    new_list.append(item)
            data[key] = new_list
    return pd.DataFrame(data)
